import re
import unittest

def parse_dimension(texto):
    if not isinstance(texto, str):
        raise ValueError("La entrada debe ser una cadena de texto.")

    texto = texto.strip()
    if not texto:
        raise ValueError("La entrada no puede estar vacía.")

    # Patrón para coincidir con número seguido de unidad (m, cm, mm)
    patron = r'^([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)\s*(m|cm|mm)$'
    match = re.match(patron, texto)

    if not match:
        raise ValueError("Formato inválido. Debe ser 'número unidad' donde la unidad es m, cm o mm.")

    numero_str, unidad = match.groups()
    try:
        numero = float(numero_str)
    except ValueError:
        raise ValueError("El valor numérico es inválido.")

    # Convertir a metros
    if unidad == 'm':
        return numero
    elif unidad == 'cm':
        return numero / 100.0
    elif unidad == 'mm':
        return numero / 1000.0
    else:
        raise ValueError("Unidad desconocida.")

class TestParseDimension(unittest.TestCase):

    def test_metros(self):
        self.assertEqual(parse_dimension("3.50 m"), 3.5)

    def test_centimetros(self):
        self.assertEqual(parse_dimension("350 cm"), 3.5)

